<script setup lang="ts">
import {nextTick,ref,useId,watch} from 'vue';
import Dropdown from '../../shell/Dropdown.vue';
import HelpHint from './HelpHint.vue';
import ThemePart from './ThemePart.vue';
import ThemeSwitch from './ThemeSwitch.vue';
import AppearanceMetricChart from './AppearanceMetricChart.vue';
import {themeParts,type ThemePart as Part} from './appearanceParts';
const props=defineProps<{editing:boolean;selected:string|null}>();
const emit=defineEmits<{select:[part:Part,element:HTMLElement]}>();
const part=(id:string)=>themeParts.find(p=>p.id===id)!;
const select=(p:Part,e:HTMLElement)=>emit('select',p,e);
const portalId=`appearance-portal-${useId().replace(/:/g,'')}`;
const name=ref('样板名称'),avatarLetter=ref('S'),enabled=ref(true),choice=ref<string|number|boolean>('daily'),nav=ref('general'),notice=ref('');
const dialog=ref<HTMLDialogElement>(),dialogOpen=ref(false);let previous:HTMLElement|null=null;
async function openDialog(event:MouseEvent){previous=event.currentTarget as HTMLElement;dialogOpen.value=true;await nextTick();dialog.value?.showModal();dialog.value?.querySelector<HTMLButtonElement>('button')?.focus();}
function closeDialog(){dialog.value?.close();dialogOpen.value=false;previous?.focus();}
watch(()=>props.editing,()=>{closeDialog();notice.value='';});
</script>
<template>
 <div class="appearance-sandbox" aria-label="Stella 交互样板">
  <div :id="portalId" class="sample-portal"/>
  <header class="sample-heading"><h3>交互样板</h3><span>示例内容 · 操作仅在此处生效</span></header>
  <div class="sample-scene">
   <ThemePart :part="part('nav')" :editing="editing" :selected="selected==='nav'" @select="select"><nav class="sample-nav" aria-label="样板导航"><strong>设置</strong><button v-for="item in [{id:'general',name:'常规'},{id:'appearance',name:'外观'},{id:'notice',name:'通知'}]" :key="item.id" type="button" :aria-current="nav===item.id?'page':undefined" @click="nav=item.id">{{item.name}}</button><button class="sample-child" type="button" @click="notice='已打开样板子项'">显示选项</button></nav></ThemePart>
   <div class="sample-main">
    <ThemePart :part="part('panel')" :editing="editing" :selected="selected==='panel'" @select="select"><div class="sample-card"><div><strong>外观预览</strong><p>文字、卡片和控件的共同层次</p></div></div></ThemePart>
    <ThemePart :part="part('input')" :editing="editing" :selected="selected==='input'" @select="select"><form class="sample-form" @submit.prevent="notice='样板表单已确认，未提交业务数据'">
     <div class="sample-avatar-row"><span>头像</span><div class="sample-inline"><span class="sample-avatar" aria-label="示例头像">{{avatarLetter}}</span><button class="st-button is-ghost" type="button" @click="avatarLetter=avatarLetter==='S'?'A':'S'">切换示例头像</button></div></div>
     <label><span>名称</span><input v-model="name" aria-label="样板名称" maxlength="80"/></label>
     <label><span>只读</span><input value="仅用于查看" aria-label="样板只读字段" readonly/></label>
     <label><span>校验</span><span><input value="" placeholder="请输入名称" aria-label="样板错误字段" aria-invalid="true" aria-describedby="sample-error"/><small id="sample-error" class="sample-error">示例错误：名称不能为空</small></span></label>
    </form></ThemePart>
    <div class="sample-inline">
     <ThemePart :part="part('switch')" :editing="editing" :selected="selected==='switch'" @select="select"><div class="sample-switch-label"><span>接收提醒</span><ThemeSwitch label="样板提醒" :checked="enabled" @change="enabled=$event"/></div></ThemePart>
     <ThemePart :part="part('overlay')" :editing="editing" :selected="selected==='overlay'" @select="select"><div class="sample-inline"><Dropdown v-model="choice" :options="[{value:'daily',label:'每日摘要'},{value:'important',label:'仅重要提醒'},{value:'off',label:'关闭提醒'}]"/><HelpHint label="样板帮助" :portal-target="`#${portalId}`">这里使用 Stella 的帮助组件；操作只影响样板。</HelpHint><button class="st-button is-ghost" type="button" @click="openDialog">打开弹层</button></div></ThemePart>
    </div>
    <div class="sample-actions">
     <ThemePart :part="part('primary')" :editing="editing" :selected="selected==='primary'" @select="select"><button class="st-button is-primary" type="button" @click="notice='样板已确认，未提交业务数据'">确认</button></ThemePart>
     <ThemePart :part="part('secondary')" :editing="editing" :selected="selected==='secondary'" @select="select"><div class="sample-inline"><button class="st-button" type="button" @click="name='样板名称';notice='样板输入已还原'">取消</button><button class="st-button is-ghost is-icon" type="button" aria-label="样板刷新" @click="notice='样板已刷新'">↻</button><button class="st-button" type="button" disabled aria-busy="true">处理中</button><button class="st-button" type="button" disabled>不可用</button></div></ThemePart>
     <ThemePart :part="part('danger')" :editing="editing" :selected="selected==='danger'" @select="select"><button class="st-button is-danger" type="button" @click="openDialog">删除示例</button></ThemePart>
    </div>
   </div>
  </div>
  <ThemePart :part="part('content')" :editing="editing" :selected="selected==='content'" @select="select"><div class="sample-table-wrap"><table><caption>内容与列表</caption><thead><tr><th>条目</th><th>说明</th><th>状态</th></tr></thead><tbody><tr class="selected-row"><td>阅读清单</td><td>选中行</td><td><span class="sample-tag">已整理</span></td></tr><tr><td>灵感笔记</td><td>普通行</td><td><span class="sample-tag pink">待阅读</span></td></tr></tbody></table></div></ThemePart>
  <ThemePart :part="part('notice')" :editing="editing" :selected="selected==='notice'" @select="select"><div class="sample-notices"><p class="success">✓ 成功：样板操作完成</p><p class="warning">! 提醒：请检查尚未填写的内容</p></div></ThemePart>
  <div class="sample-metrics"><ThemePart v-for="(kind,index) in (['cpu','memory','disk'] as const)" :key="kind" :part="part(kind)" :editing="editing" :selected="selected===kind" @select="select"><AppearanceMetricChart :kind="kind" :label="['CPU','内存','磁盘'][index]!"/></ThemePart></div>
  <ThemePart :part="part('page')" :editing="editing" :selected="selected==='page'" @select="select"><p class="sample-page">页面背景与正文 <span>次要说明</span> <small>辅助信息</small></p></ThemePart>
  <p v-if="notice" class="sample-feedback" role="status">{{notice}}</p>
  <Teleport :to="`#${portalId}`" defer><dialog v-if="dialogOpen" ref="dialog" class="sample-dialog" aria-labelledby="sample-dialog-title" @cancel.prevent="closeDialog"><h3 id="sample-dialog-title">删除这个示例？</h3><p>仅关闭此样板弹层，不删除任何数据。</p><div class="sample-actions"><button class="st-button" type="button" @click="closeDialog">取消</button><button class="st-button is-danger" type="button" @click="notice='示例操作完成，未删除数据';closeDialog()">确认删除示例</button></div></dialog></Teleport>
 </div>
</template>
