ckground:#0008}.sample-dialog h3{font-size:17px}.sample-dialog p{margin:12px 0 20px;color:var(--text-lo);font-size:14px}@media(max-width:700px){.appearance-sandbox{padding:14px}.sample-scene{grid-template-columns:1fr;gap:18px}.sample-nav{flex-direction:row;flex-wrap:wrap;align-items:center}.sample-nav strong{width:100%}.sample-nav .sample-child{padding-left:9px}.sample-metrics{gap:7px}.sample-form label{grid-template-columns:54px minmax(0,1fr);gap:8px}.sample-heading{gap:5px}.sample-actions{row-gap:14px}}@container(max-width:620px){.sample-main{grid-template-columns:minmax(0,1fr)}.sample-main>[data-theme-part="input"]{grid-row:auto}.sample-main>.sample-inline{gap:12px}.sample-main .sample-actions>[data-theme-part="secondary"]{flex-basis:auto}}
